def distance_k(root: TreeNode, target: TreeNode, k: int) -> list[int]:
    # Record parent links so the tree can be searched like an undirected graph.
    parent = {root: None}
    stack = [root]
    while stack:
        node = stack.pop()
        for child in (node.left, node.right):
            if child:
                parent[child] = node
                stack.append(child)
    # Breadth first search outward from the target, one level per step.
    frontier, seen = [target], {target}
    for _ in range(k):
        nxt = []
        for node in frontier:
            for nb in (node.left, node.right, parent[node]):
                if nb and nb not in seen:
                    seen.add(nb)
                    nxt.append(nb)
        frontier = nxt
        if not frontier:
            break
    return [node.val for node in frontier]

