def rob(nums: list[int]) -> int:
    def rob_line(lo: int, hi: int) -> int:
        # Classic straight street over nums[lo:hi].
        prev2 = prev = 0
        for i in range(lo, hi):
            prev2, prev = prev, max(prev, prev2 + nums[i])
        return prev

    n = len(nums)
    if n == 1:
        return nums[0]
    # Either the last house or the first house is left alone.
    return max(rob_line(0, n - 1), rob_line(1, n))

