class AuthenticationManager:
    def __init__(self, timeToLive: int):
        self.ttl = timeToLive
        self.expiry = OrderedDict()   # token id -> expiry, ordered by expiry

    def _purge(self, now):
        # Tokens at the front expire first; drop every one that has run out.
        while self.expiry:
            token, expires = next(iter(self.expiry.items()))
            if expires > now:
                break
            self.expiry.popitem(last=False)

    def generate(self, tokenId: str, currentTime: int) -> None:
        self._purge(currentTime)
        self.expiry[tokenId] = currentTime + self.ttl

    def renew(self, tokenId: str, currentTime: int) -> None:
        self._purge(currentTime)
        if tokenId in self.expiry:
            self.expiry[tokenId] = currentTime + self.ttl
            self.expiry.move_to_end(tokenId)

    def countUnexpiredTokens(self, currentTime: int) -> int:
        self._purge(currentTime)
        return len(self.expiry)

