def reaching_points(sx: int, sy: int, tx: int, ty: int) -> bool:
    # Walk backwards from the target; each step's parent is unique.
    while tx >= sx and ty >= sy:
        if tx == sx and ty == sy:
            return True
        if tx > ty:
            if ty == sy:
                return (tx - sx) % ty == 0   # only x can still shrink
            tx %= ty
        elif ty > tx:
            if tx == sx:
                return (ty - sy) % tx == 0   # only y can still shrink
            ty %= tx
        else:
            return False                     # equal coordinates have no parent
    return False

def k_closest(points: list[list[int]], k: int) -> list[list[int]]:
