def game_of_life(board: list[list[int]]) -> None:
    m, n = len(board), len(board[0])
    for r in range(m):
        for c in range(n):
            live = 0
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    if (dr or dc) and 0 <= r + dr < m and 0 <= c + dc < n:
                        live += board[r + dr][c + dc] & 1   # current state only
            if live == 3 or (live == 2 and board[r][c] & 1):
                board[r][c] |= 2                            # alive next generation
    for r in range(m):
        for c in range(n):
            board[r][c] >>= 1

