def max_envelopes(envelopes: list[list[int]]) -> int:
    # Width ascending; for equal widths, height descending so they cannot chain.
    envelopes = sorted(envelopes, key=lambda e: (e[0], -e[1]))
    tails = []  # tails[k] = smallest last height of an increasing run of length k+1
    for _, h in envelopes:
        k = bisect.bisect_left(tails, h)
        if k == len(tails):
            tails.append(h)
        else:
            tails[k] = h
    return len(tails)

