def can_partition(nums: list[int]) -> bool:
    total = sum(nums)
    if total % 2:
        return False
    target = total // 2
    reachable = [False] * (target + 1)
    reachable[0] = True
    for x in nums:
        # Go downward so each number is used at most once.
        for s in range(target, x - 1, -1):
            if reachable[s - x]:
                reachable[s] = True
        if reachable[target]:
            return True
    return reachable[target]

