def longest_subarray(nums: list[int], limit: int) -> int:
    maxq, minq = deque(), deque()  # decreasing and increasing candidates
    left = best = 0
    for right, x in enumerate(nums):
        while maxq and maxq[-1] < x:
            maxq.pop()
        maxq.append(x)
        while minq and minq[-1] > x:
            minq.pop()
        minq.append(x)
        while maxq[0] - minq[0] > limit:
            # Shrink from the left, dropping the outgoing value if it is a front.
            if maxq[0] == nums[left]:
                maxq.popleft()
            if minq[0] == nums[left]:
                minq.popleft()
            left += 1
        best = max(best, right - left + 1)
    return best

