def max_coins(nums: list[int]) -> int:
    vals = [1] + nums + [1]
    size = len(vals)
    # dp[l][r] = best coins from bursting every balloon strictly between l and r
    dp = [[0] * size for _ in range(size)]
    for gap in range(2, size):
        for l in range(0, size - gap):
            r = l + gap
            edge = vals[l] * vals[r]
            row_l, best = dp[l], 0
            for k in range(l + 1, r):          # k is the last balloon burst in (l, r)
                cand = row_l[k] + edge * vals[k] + dp[k][r]
                if cand > best:
                    best = cand
            row_l[r] = best
    return dp[0][size - 1]

