def accounts_merge(accounts: list[list[str]]) -> list[list[str]]:
    parent = {}
    owner = {}

    def find(x):
        root = x
        while parent[root] != root:
            root = parent[root]
        while parent[x] != root:            # path compression
            parent[x], x = root, parent[x]
        return root

    for record in accounts:
        name, first = record[0], record[1]
        for email in record[1:]:
            if email not in parent:
                parent[email] = email
                owner[email] = name
            # Every email on a record belongs with the record's first email.
            ra, rb = find(first), find(email)
            if ra != rb:
                parent[rb] = ra

    groups = defaultdict(list)
    for email in parent:
        groups[find(email)].append(email)
    return [[owner[root]] + sorted(emails) for root, emails in groups.items()]

