def next_greater_elements(nums: list[int]) -> list[int]:
    n = len(nums)
    result = [-1] * n
    waiting = []   # indices still looking for a greater value
    for i in range(2 * n):
        value = nums[i % n]
        while waiting and nums[waiting[-1]] < value:
            result[waiting.pop()] = value
        if i < n:
            waiting.append(i)   # only the first lap adds new indices
