def shortest_path(grid: list[list[int]], k: int) -> int:
    rows, cols = len(grid), len(grid[0])
    target = (rows - 1, cols - 1)
    if k >= rows + cols - 2:
        return rows + cols - 2           # enough budget for the straight route
    best = [[-1] * cols for _ in range(rows)]   # most demolitions left on arrival
    best[0][0] = k
    queue = deque([(0, 0, k)])
    steps = 0
    while queue:
        for _ in range(len(queue)):
            r, c, left = queue.popleft()
            if (r, c) == target:
                return steps
            for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
                if 0 <= nr < rows and 0 <= nc < cols:
                    remain = left - grid[nr][nc]
                    if remain > best[nr][nc]:    # only explore strictly better states
                        best[nr][nc] = remain
                        queue.append((nr, nc, remain))
        steps += 1
    return -1

