def find_anagrams(s: str, p: str) -> list[int]:
    n, m = len(s), len(p)
    if m > n:
        return []
    need = [0] * 26
    have = [0] * 26
    for ch in p:
        need[ord(ch) - 97] += 1
    matched = sum(1 for c in range(26) if need[c] == 0)  # letters already equal

    def change(c: int, delta: int) -> None:
        nonlocal matched
        if have[c] == need[c]:
            matched -= 1          # was equal, about to differ
        have[c] += delta
        if have[c] == need[c]:
            matched += 1

    result = []
    for i in range(n):
        change(ord(s[i]) - 97, 1)            # letter enters on the right
        if i >= m:
            change(ord(s[i - m]) - 97, -1)   # letter leaves on the left
        if i >= m - 1 and matched == 26:
            result.append(i - m + 1)
    return result

def longest_str_chain(words: list[str]) -> int:
    best = {}  # longest chain ending at each processed word
    answer = 0
    for word in sorted(words, key=len):
        length = 1
        for i in range(len(word)):
            prev = word[:i] + word[i + 1:]     # remove one letter
            if prev in best and best[prev] + 1 > length:
                length = best[prev] + 1
        best[word] = max(best.get(word, 0), length)
        answer = max(answer, length)
    return answer

