def combination_sum2(candidates: list[int], target: int) -> list[list[int]]:
    nums = sorted(candidates)
    result, path = [], []

    def search(start, remaining):
        if remaining == 0:
            result.append(path[:])
            return
        for i in range(start, len(nums)):
            if nums[i] > remaining:
                break                        # sorted: nothing later fits
            if i > start and nums[i] == nums[i - 1]:
                continue                     # same value already tried at this depth
            path.append(nums[i])
            search(i + 1, remaining - nums[i])
            path.pop()

    search(0, target)
    return result

