def find_ladders(beginWord: str, endWord: str, wordList: list[str]) -> list[list[str]]:
    words = set(wordList)
    if endWord not in words:
        return []
    letters = "abcdefghijklmnopqrstuvwxyz"
    parents = defaultdict(list)   # word -> words one level earlier that reach it
    level = {beginWord}
    words.discard(beginWord)
    found = False
    while level and not found:
        next_level = set()
        for word in level:
            for i in range(len(word)):
                prefix, suffix = word[:i], word[i + 1:]
                for ch in letters:
                    nxt = prefix + ch + suffix
                    if nxt in words:
                        if nxt == endWord:
                            found = True
                        next_level.add(nxt)
                        parents[nxt].append(word)
        words -= next_level      # mark visited only after the whole level
        level = next_level
    if not found:
        return []
    # Walk predecessor links backward from endWord, iteratively.
    results = []
    stack = [[endWord]]
    while stack:
        path = stack.pop()
        last = path[-1]
        if last == beginWord:
            results.append(path[::-1])
            continue
        for prev in parents[last]:
            stack.append(path + [prev])
    return results

