def shortest_distance(grid: list[list[int]]) -> int:
    rows, cols = len(grid), len(grid[0])
    total = [[0] * cols for _ in range(rows)]
    # Empty cells reached by every BFS so far are marked with -runs.
    mark = [[0] * cols for _ in range(rows)]
    buildings = [(r, c) for r in range(rows) for c in range(cols) if grid[r][c] == 1]
    best = -1
    for runs, (sr, sc) in enumerate(buildings):
        best = -1
        queue = deque([(sr, sc)])
        dist = 0
        while queue:
            dist += 1
            for _ in range(len(queue)):
                r, c = queue.popleft()
                for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
                    # Only cells that are empty and reached by all previous runs.
                    if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == 0 and mark[nr][nc] == -runs:
                        mark[nr][nc] -= 1
                        total[nr][nc] += dist
                        queue.append((nr, nc))
                        if best == -1 or total[nr][nc] < best:
                            best = total[nr][nc]
        if best == -1:
            return -1   # no empty cell is reachable from every building so far
    return best

