def maximal_rectangle(matrix: list[list[str]]) -> int:
    cols = len(matrix[0])
    heights = [0] * (cols + 1)   # extra 0 bar flushes the stack each row
    best = 0
    for row in matrix:
        for c in range(cols):
            heights[c] = heights[c] + 1 if row[c] == "1" else 0
        stack = [-1]   # indices of bars with increasing heights
        for c in range(cols + 1):
            while stack[-1] != -1 and heights[stack[-1]] >= heights[c]:
                h = heights[stack.pop()]
                width = c - stack[-1] - 1
                best = max(best, h * width)
