def collect_the_coins(coins: list[int], edges: list[list[int]]) -> int:
    n = len(coins)
    adj = [[] for _ in range(n)]
    for a, b in edges:
        adj[a].append(b)
        adj[b].append(a)
    degree = [len(nbrs) for nbrs in adj]
    removed = [False] * n
    edges_left = n - 1

    def cut(u: int) -> None:
        # Remove leaf u together with its single remaining edge.
        nonlocal edges_left
        removed[u] = True
        degree[u] = 0
        edges_left -= 1
        for v in adj[u]:
            if not removed[v]:
                degree[v] -= 1

    # 1) Peel coinless leaves until every leaf holds a coin.
    queue = deque(u for u in range(n) if degree[u] == 1 and coins[u] == 0)
    while queue:
        u = queue.popleft()
        if removed[u] or degree[u] != 1:
            continue
        cut(u)
        for v in adj[u]:
            if not removed[v] and degree[v] == 1 and coins[v] == 0:
                queue.append(v)

    # 2) Peel two full layers of leaves; their coins are collected from distance 2.
    for _ in range(2):
        leaves = [u for u in range(n) if not removed[u] and degree[u] == 1]
        for u in leaves:
            if degree[u] == 1:   # its partner may have been cut already
                cut(u)

    return 2 * max(0, edges_left)

def check_inclusion(s1: str, s2: str) -> bool:
    m, n = len(s1), len(s2)
    if m > n:
        return False
    need = [0] * 26
    have = [0] * 26
    for ch in s1:
        need[ord(ch) - 97] += 1
    matched = sum(1 for c in range(26) if need[c] == 0)

    def change(c: int, delta: int) -> None:
        nonlocal matched
        if have[c] == need[c]:
            matched -= 1
        have[c] += delta
        if have[c] == need[c]:
            matched += 1

    for i in range(n):
        change(ord(s2[i]) - 97, 1)             # enters on the right
        if i >= m:
            change(ord(s2[i - m]) - 97, -1)    # leaves on the left
        if matched == 26:
            return True
    return False

